#[cfg(target_arch = "aarch64")]
fn time(name: &str, f: unsafe extern "C" fn(*mut u64)) {
    let mut s = vec![0u64; 1024];
    let mut best = f64::MAX;
    for _ in 0..30 {
        for (i, w) in s.iter_mut().enumerate().skip(8) {
            *w = 0xffff_ffff_ffff - (i as u64) * 977;
        }
        let t = std::time::Instant::now();
        for _ in 0..20000 {
            unsafe { f(s.as_mut_ptr()) };
        }
        best = best.min(t.elapsed().as_nanos() as f64 / 20000.0);
    }
    eprintln!("SEG {name} {best:.2} ns");
}

#[cfg(target_arch = "aarch64")]
pub fn bench(_: &mut Criterion) {
    time("chain", vgs_chain);
    time("step_orig", vgs_step_orig);
    time("step_hyb", vgs_step_hyb);
    time("step_seq", vgs_step_seq);
}

#[cfg(not(target_arch = "aarch64"))]
pub fn bench(_: &mut Criterion) {}
